export function useChatInputController(component) {
  return {
    editMessage: null,
    editMessageId: null,
    cursorWord: {},
    editorText: '',
    previousEditorText: '',
    textProfileNames: [],
    selectorProfileNames: [],

    setEditorText(text) {
      component.$refs.inputBox?.setEditorText(text)
    },
    onMessageChange() {
      const text = component.$refs.inputBox?.getEditorText() ?? ''
      if (text !== this.editorText) this.editorText = text
    },
    updateCursorWord() {
      this.cursorWord = component.$refs.inputBox?.getCaretWordInfo() ?? {}
    },
    onEditMessage(message) {
      // ... existing logic
    },
    onResetEdit() {
      // ... existing logic
    },
    // ... all other edit-related methods
  }
}

export function useChatFileController(component, chatService) {
  return {
    previewFile: null,
    notebookStatus: null,

    onAddFile(file) {
      if (!this.hasFileInChat(file) && chatService.addFileToChat({ chat: component.chat, file })) {}
    },
    hasFileInChat(file) {
      return this.hasFile(file, component.chatFiles)
    },
    normalizeFilePath(path) {
      return path?.toLowerCase().trim() || ''
    },
    // ... all file methods
  }
}
